#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-component-tokens.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-component-tokens.mjs
 *
 * @version 2
 * @updated 2026-06-05
 *
 * Component source files are discovered via the shared `_discover-components.mjs`
 * helper (path-agnostic: components/ui/, generic components/, and feature-located
 * <feature>/components/), NOT only src/components/ui/.
 *
 * Enforces token discipline in design-system component sources. Scans every
 * .tsx file under src/components/ui/<Name>/ and refuses commits that contain
 * hardcoded color values or palette-shade Tailwind classes.
 *
 * Allowed: Tailwind v4 arbitrary values referencing CSS vars
 *   bg-[var(--color-primary)] / text-[var(--color-foreground)] / border-[var(--color-border)]
 *
 * Forbidden in src/components/ui/**\/*.tsx :
 *   - hex literals:  #[0-9a-fA-F]{3,8}
 *   - rgb/rgba/hsl/hsla function literals
 *   - palette-shade Tailwind classes (bg-amber-500, text-red-300, etc.)
 *
 * Exemptions:
 *   - src/components/shadcn/ (regenerated by shadcn CLI; never hand-edited)
 *   - src/styles/ (token + state-utility sources)
 *   - __stories__/ (demo-only)
 *   - __tests__/   (assertions may include raw strings)
 *
 * Usage:
 *   node verify-component-tokens.mjs [src-root]
 *   default src-root: "src"
 *
 * Exit: 0 on green, 1 on any violation.
 *
 * Per COMPONENT_CREATION.yaml.verifiers.verify-component-tokens.
 */

import { readdirSync, readFileSync, existsSync, statSync } from "node:fs";
import { join, relative, dirname } from "node:path";
import { makeIsUnderComponent, makeComponentDirOf } from "./_discover-components.mjs";
import { applyExceptions } from "./_load-exceptions.mjs";

const RULE_ID = "verify-component-tokens";
const SRC_ROOT = process.argv[2] || "src";
const REPO_ROOT = process.cwd();
const absRoot = join(REPO_ROOT, SRC_ROOT);
const isUnderComponent = makeIsUnderComponent(absRoot);
const componentDirOf = makeComponentDirOf(absRoot);

const IGNORE_DIRS = new Set([
  "node_modules", ".next", ".turbo", "dist", "build", "coverage", ".git",
  "storybook-static",
]);

const SHADCN_SEGMENT = /[\\/]components[\\/]shadcn[\\/]/;
const STYLES_SEGMENT = /[\\/]styles[\\/]/;
const STORIES_SEGMENT = /[\\/]__stories__[\\/]/;
const TESTS_SEGMENT = /[\\/]__tests__[\\/]/;
const SPECS_SEGMENT = /[\\/]__specs__[\\/]/;

// Tailwind palettes that produce shade-class violations.
// Generated from Tailwind's default palette (v4).
const PALETTE_NAMES = [
  "slate", "gray", "zinc", "neutral", "stone",
  "red", "orange", "amber", "yellow", "lime",
  "green", "emerald", "teal", "cyan", "sky",
  "blue", "indigo", "violet", "purple", "fuchsia",
  "pink", "rose",
];

// Class-utility prefixes that take a color name.
const COLOR_UTILITY_PREFIXES = [
  "bg", "text", "border", "ring", "outline",
  "fill", "stroke", "from", "via", "to",
  "shadow", "accent", "caret", "decoration",
  "divide", "placeholder",
];

// e.g. "bg-amber-500", "text-red-300", "ring-blue-400/50"
const PALETTE_CLASS_REGEX = new RegExp(
  String.raw`\b(${COLOR_UTILITY_PREFIXES.join("|")})-(${PALETTE_NAMES.join("|")})-(50|100|200|300|400|500|600|700|800|900|950)(?:\/\d+)?\b`,
  "g",
);

// Hex literals: #fff, #ffffff, #ffffff00. Excludes URL fragments like #section.
const HEX_REGEX = /(?<![A-Za-z0-9])#[0-9a-fA-F]{3,8}\b/g;

// rgb / rgba / hsl / hsla function literals.
const RGB_HSL_REGEX = /\b(?:rgb|rgba|hsl|hsla)\s*\(/g;

if (!existsSync(absRoot)) {
  process.stdout.write(
    `✅ verify-component-tokens — no ${SRC_ROOT}/ in this repo; nothing to check.\n`,
  );
  process.exit(0);
}

const componentFiles = [];

function walk(dir) {
  let entries;
  try {
    entries = readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      if (IGNORE_DIRS.has(entry.name)) continue;
      walk(full);
      continue;
    }
    if (!entry.isFile()) continue;
    if (!/\.tsx?$/.test(entry.name)) continue;
    // Only check files inside a discovered component folder.
    if (!isUnderComponent(full)) continue;
    // Exemptions.
    if (SHADCN_SEGMENT.test(full)) continue;
    if (STYLES_SEGMENT.test(full)) continue;
    if (STORIES_SEGMENT.test(full)) continue;
    if (TESTS_SEGMENT.test(full)) continue;
    if (SPECS_SEGMENT.test(full)) continue;
    componentFiles.push(full);
  }
}

walk(absRoot);

if (componentFiles.length === 0) {
  process.stdout.write(
    `✅ verify-component-tokens — no design-system component sources under ${SRC_ROOT}/ (components/ui, components/, or feature-located components/).\n`,
  );
  process.exit(0);
}

const violations = [];
// Collect per-file violations grouped by the owning component folder, so a
// per-feature exception.yaml can waive a component's violations (with a logged reason).
const byDir = new Map(); // compDir -> string[]

function lineNumber(content, idx) {
  return content.slice(0, idx).split("\n").length;
}

function* scanRegex(re, content) {
  const flags = re.flags.includes("g") ? re.flags : re.flags + "g";
  const r = new RegExp(re.source, flags);
  let m;
  while ((m = r.exec(content)) !== null) {
    yield { match: m[0], index: m.index };
  }
}

for (const filePath of componentFiles) {
  const rel = relative(REPO_ROOT, filePath);
  const content = readFileSync(filePath, "utf8");
  const local = [];

  // Hex literals.
  for (const hit of scanRegex(HEX_REGEX, content)) {
    local.push(
      `${rel}:${lineNumber(content, hit.index)}: hardcoded hex color "${hit.match}" — use Tailwind arbitrary value referencing a CSS var (bg-[var(--color-…)])`,
    );
  }

  // rgb/hsl literals.
  for (const hit of scanRegex(RGB_HSL_REGEX, content)) {
    local.push(
      `${rel}:${lineNumber(content, hit.index)}: ${hit.match.replace("(", "").trim()}() literal — use a CSS var instead`,
    );
  }

  // Palette-shade classes.
  for (const hit of scanRegex(PALETTE_CLASS_REGEX, content)) {
    local.push(
      `${rel}:${lineNumber(content, hit.index)}: palette-shade class "${hit.match}" — use Tailwind arbitrary value referencing a CSS var instead`,
    );
  }

  if (local.length) {
    const compDir = componentDirOf(filePath) || dirname(filePath);
    if (!byDir.has(compDir)) byDir.set(compDir, []);
    byDir.get(compDir).push(...local);
  }
}

for (const [compDir, local] of byDir) {
  const rel = relative(REPO_ROOT, compDir);
  violations.push(
    ...applyExceptions({ dir: compDir, ruleId: RULE_ID, violations: local, rel }),
  );
}

if (violations.length === 0) {
  process.stdout.write(
    `✅ verify-component-tokens — ${componentFiles.length} component file(s) checked; all token-disciplined.\n`,
  );
  process.exit(0);
}

process.stderr.write(
  `❌ verify-component-tokens: ${violations.length} violation(s)\n\n`,
);
for (const v of violations) process.stderr.write(`  ${v}\n`);
process.stderr.write(
  `\nPer COMPONENT_CREATION.yaml.token_discipline, components must reference CSS vars only.\n` +
    `Allowed: bg-[var(--color-primary)], text-[var(--color-foreground)], etc.\n` +
    `Forbidden in src/components/ui/**/*.tsx: hex literals, rgb()/hsl() calls, palette-shade classes.\n`,
);
process.exit(1);
